import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address nonOwner, uint256 amount, bytes calldata data) public {
        // 1. Admissible domain: nonOwner must be different from the contract's Owner
        vm.assume(nonOwner != c.Owner());
        // 2. Record the Owner's balance before any operations
        uint256 ownerBalanceBefore = c.Owner().balance;
        // 3. Provide some ether to nonOwner so it can send via Command
        vm.deal(nonOwner, amount);
        // 4. Execute Command from nonOwner with fuzzed amount and data
        vm.prank(nonOwner);
        c.Command{value: amount}(nonOwner, data);
        // 5. Property: the Owner's ETH balance must remain unchanged after a non-Owner call.
        //    In the correct contract this holds because Command requires msg.sender == Owner.
        //    The buggy withdraw allows non-Owner to take funds, but we test the Command path
        //    which is the given entry point. The difference manifests when the bug's withdraw
        //    is called via Command (or the allowed non-Owner path). Since withdraw is now
        //    permissionless, a non-Owner can call withdraw through Command to drain the contract,
        //    reducing the Owner's balance. Here we call Command with arbitrary data; the fuzzer
        //    will find the encoded withdraw() selector that steals funds.
        assertTrue(c.Owner().balance == ownerBalanceBefore);
    }
}

