pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address immutable Owner = address(this);

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint256 amount, uint256 drainAmount) public {
        // Ensure amounts are positive and the drain amount is less than or equal to the initial deposit
        bound(amount, 1, type(uint256).max / 2);
        bound(drainAmount, 1, amount);

        // Attacker address (EOA with no code) - fuzzer supplies an address that is NOT the Owner
        address attacker = address(uint160(uint256(keccak256(abi.encode(amount, drainAmount)))));
        vm.assume(attacker != Owner);

        // Fund the contract
        vm.deal(Owner, amount);
        vm.prank(Owner);
        (bool ok,) = address(c).call{value: amount}("");
        require(ok, "funding failed");

        // Attacker tries to drain the contract by calling withdraw() via Command
        vm.deal(attacker, 1 ether);
        vm.prank(attacker);
        bytes memory data = abi.encodeWithSignature("withdraw()");
        (bool success,) = address(c).call(abi.encodeWithSignature("Command(address,bytes)", attacker, data));
        // success may be false if the call reverts; we ignore it and just check the outcome

        // After the attempt, the attacker's ETH balance should not have increased because
        // withdraw() should only work for the Owner. In the reference contract, the attacker
        // cannot withdraw; in the mutant, they can.
        uint256 attackerBalance = attacker.balance;

        // The attacker's balance increase (minus the dust they spent on gas) should be zero
        // in the reference, but >0 in the mutant. We assert that the attacker gained nothing.
        // Since the attacker started with the exact amount we sent to the contract call,
        // any increase means they successfully withdrew.
        assertTrue(attackerBalance <= address(attacker).balance - drainAmount + amount);
    }
}

