contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address adr, bytes memory data) public {
        // Ensure Owner is the only one who can call Command; we fuzz adr and data as arguments.
        // Deploy a reverter helper that makes any call fail, to trigger the buggy behavior.
        address reverter = address(new Reverter());
        // Fund the contract with some Ether to observe balance changes.
        vm.deal(address(c), 100 ether);
