        // The key property: if the Command call reverts (ok == false), the contract balance must remain unchanged.
        // The buggy version (missing require) may alter balance via withdraw logic etc. - but here we test balance invariance after a failed Command.
        assertTrue(!ok || address(c).balance == balanceBefore, "Balance should not change on failed Command");
    }
}
contract Reverter {
    fallback() external payable { revert(); }
    receive() external payable { revert(); }
}

